"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import {
  type ChartStatus,
  ChartDataTable,
  ChartState,
  EASE,
  Keyframes,
  Stat,
  formatCount,
  mulberry32,
  niceTicks,
  useElementWidth,
  useHoverIndexKeys,
  usePrefersReducedMotion,
} from "@/components/moneytrees/charts/chart-engine";

function generateLatency(seed: number, n: number, mu: number, sigma: number): number[] {
  const rand = mulberry32(seed);
  const out: number[] = [];
  for (let i = 0; i < n; i += 1) {
    const u1 = Math.max(1e-9, rand());
    const u2 = rand();
    const z = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
    out.push(Math.exp(mu + sigma * z));
  }
  return out;
}

export const LATENCY_MS = generateLatency(0xd1ce, 900, 3.4, 0.55);
export const ORDER_VALUES = generateLatency(0xcafe, 700, 4.05, 0.42);

function niceStep(raw: number) {
  const mag = Math.pow(10, Math.floor(Math.log10(raw)));
  const norm = raw / mag;
  return (norm >= 7.5 ? 10 : norm >= 3.5 ? 5 : norm >= 2.25 ? 2.5 : norm >= 1.5 ? 2 : 1) * mag;
}

export type Bin = { from: number; to: number; count: number };

export function buildBins(samples: number[], target = 26): Bin[] {
  if (!samples.length) return [];
  let min = Infinity;
  let max = -Infinity;
  for (const v of samples) {
    min = Math.min(min, v);
    max = Math.max(max, v);
  }
  const step = niceStep((max - min) / target || 1);
  const lo = Math.floor(min / step) * step;
  const count = Math.max(1, Math.ceil((max - lo) / step));
  const bins: Bin[] = Array.from({ length: count }, (_, i) => ({
    from: lo + i * step,
    to: lo + (i + 1) * step,
    count: 0,
  }));
  for (const v of samples) {
    const index = Math.min(count - 1, Math.floor((v - lo) / step));
    bins[index]!.count += 1;
  }
  return bins;
}

export function percentile(samples: number[], k: number): number {
  if (!samples.length) return 0;
  const sorted = [...samples].sort((a, b) => a - b);
  return sorted[Math.min(sorted.length - 1, Math.floor((k / 100) * (sorted.length - 1)))]!;
}

// A long tail binned to its maximum leaves most of the plot empty, so samples past
// the cutoff fold into one detached overflow bin; `tailCutoff: 100` bins the full range.
export function splitTail(samples: number[], cutoffPercentile: number) {
  if (cutoffPercentile >= 100 || !samples.length) {
    return { body: samples, tail: [] as number[], cutoff: Infinity };
  }
  const cutoff = percentile(samples, cutoffPercentile);
  const body: number[] = [];
  const tail: number[] = [];
  for (const value of samples) (value <= cutoff ? body : tail).push(value);
  return body.length ? { body, tail, cutoff } : { body: samples, tail: [], cutoff: Infinity };
}

const PAD = { top: 34, right: 46, bottom: 26, left: 12 };

// Percentiles are one ordered quantity, so they share one hue that darkens with k;
// three unrelated colours read as a judgement (red p99 = "bad") the chart should not make.
function pinInk(index: number, count: number) {
  const weight = 45 + (count <= 1 ? 55 : (index / (count - 1)) * 55);
  return `color-mix(in srgb, var(--spectrum-series-1) ${weight.toFixed(0)}%, var(--spectrum-chart-surface))`;
}

export interface HistogramChartProps {
  className?: string;
  data: number[];
  label?: string;
  format?: (value: number) => string;
  percentiles?: number[];
  /** Percentile past which samples fold into one overflow bin. 100 disables it. */
  tailCutoff?: number;
  bins?: number;
  height?: number;
  status?: ChartStatus;
  onRetry?: () => void;
}

type Format = (value: number) => string;
type Scale = (v: number) => number;
type Pin = { k: number; value: number };

function sampleWord(count: number): string {
  return count === 1 ? "sample" : "samples";
}

function sharePct(count: number, total: number): string {
  return ((count / Math.max(1, total)) * 100).toFixed(1);
}

function riseStyle(reduce: boolean, delayMs: number): React.CSSProperties {
  return {
    transition: reduce ? undefined : "opacity 150ms ease-out",
    transformBox: "fill-box",
    transformOrigin: "bottom center",
    animation: reduce ? undefined : `spectrum-mc-rise 420ms ${EASE} ${delayMs}ms both`,
  };
}

function activeBin(bins: Bin[], hover: number | null): Bin | null {
  if (hover == null || hover >= bins.length) return null;
  return bins[hover] ?? null;
}

function tailSummary(hasTail: boolean, tailCount: number, cutoff: number, format: Format): string {
  return hasTail ? ` · ${formatCount(tailCount)} past ${format(cutoff)}` : "";
}

function histogramAriaLabel(
  label: string,
  total: number,
  n: number,
  hasTail: boolean,
  tailCount: number,
  cutoff: number,
  pins: Pin[],
  format: Format,
): string {
  const overflow = hasTail
    ? `, with ${formatCount(tailCount)} samples at or above ${format(cutoff)} in an overflow bin`
    : "";
  const marks = pins.map((p) => `p${p.k} ${format(p.value)}`).join(", ");
  return `${label} distribution: ${formatCount(total)} samples across ${n} bins${overflow}. ${marks}.`;
}

function hoverText(
  tailActive: boolean,
  active: Bin | null,
  tailCount: number,
  cutoff: number,
  total: number,
  format: Format,
): string {
  if (tailActive) {
    return `${format(cutoff)} and above · ${formatCount(tailCount)} ${sampleWord(tailCount)} · ${sharePct(tailCount, total)}% · the tail`;
  }
  if (active) {
    return `${format(active.from)} – ${format(active.to)} · ${formatCount(active.count)} ${sampleWord(active.count)} · ${sharePct(active.count, total)}%`;
  }
  return " ";
}

function histogramRows(
  bins: Bin[],
  hasTail: boolean,
  tailCount: number,
  cutoff: number,
  total: number,
  format: Format,
): (string | number)[][] {
  const rows: (string | number)[][] = bins.map((bin) => [
    `${format(bin.from)} – ${format(bin.to)}`,
    bin.count,
    `${sharePct(bin.count, total)}%`,
  ]);
  if (hasTail)
    rows.push([`${format(cutoff)} and above`, tailCount, `${sharePct(tailCount, total)}%`]);
  return rows;
}

function histogramLayout(width: number, height: number, n: number, hasTail: boolean) {
  const w = Math.max(width, 300);
  const x0 = PAD.left;
  const x1 = w - PAD.right;
  const y0 = PAD.top;
  const y1 = height - PAD.bottom;
  const plotW = Math.max(1, x1 - x0);
  const tailGap = 16;
  const tailW = hasTail ? Math.max(12, plotW * 0.04) : 0;
  const bodyW = Math.max(1, plotW - (hasTail ? tailW + tailGap : 0));
  const tailX = x0 + bodyW + tailGap;
  const binW = bodyW / Math.max(n, 1);
  const barW = Math.max(1, binW - 1);
  return { w, h: height, x0, x1, y0, y1, tailGap, tailW, bodyW, tailX, binW, barW };
}

type Layout = ReturnType<typeof histogramLayout>;

function useHistogramBins(
  data: number[],
  tailCutoff: number,
  binTarget: number,
  percentiles: number[],
) {
  const { body, tail, cutoff } = React.useMemo(
    () => splitTail(data, tailCutoff),
    [data, tailCutoff],
  );
  const binsData = React.useMemo(() => buildBins(body, binTarget), [body, binTarget]);
  const maxCount = React.useMemo(
    () => Math.max(1, ...binsData.map((bin) => bin.count), tail.length),
    [binsData, tail.length],
  );
  const pins = React.useMemo<Pin[]>(
    () => percentiles.map((k) => ({ k, value: percentile(data, k) })),
    [data, percentiles],
  );
  return { tail, cutoff, binsData, maxCount, pins };
}

function useHistogramScales(binsData: Bin[], maxCount: number, layout: Layout) {
  const { x0, y0, y1, bodyW } = layout;
  const domainLo = binsData[0]?.from ?? 0;
  const domainHi = binsData[binsData.length - 1]?.to ?? 1;
  const xOf = React.useCallback(
    (v: number) => x0 + ((v - domainLo) / (domainHi - domainLo || 1)) * bodyW,
    [x0, bodyW, domainLo, domainHi],
  );
  const yOf = React.useCallback(
    (count: number) => y1 - (count / maxCount) * (y1 - y0),
    [y0, y1, maxCount],
  );
  const countTicks = React.useMemo(() => niceTicks(0, maxCount, 3), [maxCount]);
  const edgeTicks = React.useMemo(() => niceTicks(domainLo, domainHi, 5), [domainLo, domainHi]);
  return { xOf, yOf, countTicks, edgeTicks };
}

function useHistogramHover(n: number, hasTail: boolean, layout: Layout) {
  const [hover, setHover] = React.useState<number | null>(null);
  const svgRef = React.useRef<SVGSVGElement | null>(null);
  const { w, x0, bodyW, tailX, tailGap } = layout;
  const onMove = (clientX: number) => {
    const svg = svgRef.current;
    if (!svg) return;
    const box = svg.getBoundingClientRect();
    const x = ((clientX - box.left) / box.width) * w;
    if (hasTail && x >= tailX - tailGap / 2) {
      setHover(n);
      return;
    }
    setHover(Math.max(0, Math.min(n - 1, Math.floor(((x - x0) / bodyW) * n))));
  };
  const onKeyDown = useHoverIndexKeys({ count: hasTail ? n + 1 : n, setIndex: setHover });
  return { hover, setHover, svgRef, onMove, onKeyDown };
}

function HistogramHeader({
  label,
  status,
  total,
  n,
  hasTail,
  tailCount,
  cutoff,
  pins,
  format,
}: {
  label: string;
  status: ChartStatus;
  total: number;
  n: number;
  hasTail: boolean;
  tailCount: number;
  cutoff: number;
  pins: Pin[];
  format: Format;
}) {
  return (
    <div className="mb-3 flex flex-wrap items-end justify-between gap-x-4 gap-y-2">
      <div>
        <p className="font-mono text-[12px] font-medium tracking-wide text-foreground">{label}</p>
        <p className="mt-0.5 font-mono text-[11px] tabular-nums text-muted-foreground">
          <Stat ready={status === "ready"}>
            {formatCount(total)} samples · {n} bins
            {tailSummary(hasTail, tailCount, cutoff, format)}
          </Stat>
        </p>
      </div>
      <p className="flex items-center gap-3 font-mono text-[11px] tabular-nums text-muted-foreground">
        <Stat ready={status === "ready"}>
          {pins.map((pin, index) => (
            <span key={pin.k} className="inline-flex items-center gap-1.5">
              <span
                aria-hidden
                className="size-1.5 rounded-full"
                style={{ background: pinInk(index, pins.length) }}
              />
              p{pin.k} <span className="font-medium text-foreground">{format(pin.value)}</span>
            </span>
          ))}
        </Stat>
      </p>
    </div>
  );
}

function HistogramAxes({
  layout,
  xOf,
  yOf,
  countTicks,
  edgeTicks,
  format,
}: {
  layout: Layout;
  xOf: Scale;
  yOf: Scale;
  countTicks: number[];
  edgeTicks: number[];
  format: Format;
}) {
  const { x0, x1, y1 } = layout;
  return (
    <>
      <g shapeRendering="crispEdges">
        {countTicks.map((tick) =>
          tick === 0 ? null : (
            <line
              key={tick}
              x1={x0}
              x2={x1}
              y1={yOf(tick)}
              y2={yOf(tick)}
              stroke="currentColor"
              strokeOpacity={0.14}
            />
          ),
        )}
        <line x1={x0} x2={x1} y1={y1} y2={y1} stroke="currentColor" strokeOpacity={0.28} />
      </g>
      <g className="font-mono">
        {countTicks.map((tick) =>
          tick === 0 ? null : (
            <text
              key={tick}
              x={x1 + 8}
              y={yOf(tick)}
              dominantBaseline="middle"
              fontSize={10.5}
              fill="currentColor"
              className="tabular-nums"
            >
              {formatCount(tick)}
            </text>
          ),
        )}
        {edgeTicks.map((tick) => {
          const x = xOf(tick);
          if (x < x0 - 1 || x > x1 + 1) return null;
          return (
            <text
              key={tick}
              x={x}
              y={y1 + 15}
              textAnchor="middle"
              fontSize={10.5}
              fill="currentColor"
              className="tabular-nums"
            >
              {format(tick)}
            </text>
          );
        })}
      </g>
    </>
  );
}

function HistogramBars({
  binsData,
  maxCount,
  layout,
  xOf,
  hover,
  reduce,
}: {
  binsData: Bin[];
  maxCount: number;
  layout: Layout;
  xOf: Scale;
  hover: number | null;
  reduce: boolean;
}) {
  const { y0, y1, binW, barW } = layout;
  const n = binsData.length;
  return (
    <>
      {binsData.map((bin, index) => {
        const barH = Math.max(bin.count > 0 ? 1.5 : 0, (bin.count / maxCount) * (y1 - y0));
        const dim = hover != null && hover !== index;
        return (
          <g key={bin.from}>
            <rect x={xOf(bin.from)} y={y0} width={binW} height={y1 - y0} fill="transparent" />
            {bin.count > 0 ? (
              <rect
                x={xOf(bin.from) + (binW - barW) / 2}
                y={y1 - barH}
                width={barW}
                height={barH}
                fill="var(--spectrum-series-1)"
                opacity={dim ? 0.55 : 1}
                style={riseStyle(reduce, (index / Math.max(1, n - 1)) * 300)}
              />
            ) : null}
          </g>
        );
      })}
    </>
  );
}

function TailBin({
  hasTail,
  tailCount,
  maxCount,
  cutoff,
  layout,
  hover,
  tailActive,
  reduce,
  format,
}: {
  hasTail: boolean;
  tailCount: number;
  maxCount: number;
  cutoff: number;
  layout: Layout;
  hover: number | null;
  tailActive: boolean;
  reduce: boolean;
  format: Format;
}) {
  if (!hasTail) return null;
  const { y0, y1, tailX, tailW, tailGap } = layout;
  const tailH = Math.max(1.5, (tailCount / maxCount) * (y1 - y0));
  const dim = hover != null && !tailActive;
  return (
    <g>
      <rect x={tailX} y={y0} width={tailW} height={y1 - y0} fill="transparent" />
      {/* Two strokes across the baseline: the axis breaks here, and
          a reader should see that rather than infer it from a gap. */}
      <g stroke="currentColor" strokeOpacity={0.45} strokeWidth={1}>
        <line x1={tailX - tailGap / 2 - 3} x2={tailX - tailGap / 2 + 1} y1={y1 + 4} y2={y1 - 4} />
        <line x1={tailX - tailGap / 2 + 1} x2={tailX - tailGap / 2 + 5} y1={y1 + 4} y2={y1 - 4} />
      </g>
      <rect
        x={tailX}
        y={y1 - tailH}
        width={tailW}
        height={tailH}
        fill="var(--spectrum-series-1)"
        opacity={dim ? 0.4 : 0.72}
        style={riseStyle(reduce, 300)}
      />
      <text
        x={tailX + tailW / 2}
        y={y1 + 15}
        textAnchor="middle"
        fontSize={10.5}
        fill="currentColor"
        className="font-mono tabular-nums"
      >
        ≥{format(cutoff)}
      </text>
    </g>
  );
}

function PercentilePins({
  pins,
  layout,
  xOf,
  reduce,
  format,
}: {
  pins: Pin[];
  layout: Layout;
  xOf: Scale;
  reduce: boolean;
  format: Format;
}) {
  const { x0, y0, y1, bodyW } = layout;
  return (
    <>
      {pins.map((pin, index) => {
        const text = `p${pin.k} ${format(pin.value)}`;
        const half = text.length * 3.1;
        const rule = Math.min(x0 + bodyW, xOf(pin.value));
        const x = Math.max(x0 + half, Math.min(x0 + bodyW - half, rule));
        const ink = pinInk(index, pins.length);
        return (
          <g
            key={pin.k}
            style={reduce ? undefined : { animation: `spectrum-mc-fade 400ms ease-out 380ms both` }}
          >
            <line x1={rule} x2={rule} y1={y0 - 6} y2={y1} stroke={ink} strokeWidth={1.25} />
            <circle cx={rule} cy={y0 - 6} r={2.5} fill={ink} />
            <text
              x={x}
              y={y0 - 14}
              textAnchor="middle"
              fontSize={10}
              fontWeight={500}
              fill="currentColor"
              className="font-mono tabular-nums text-muted-foreground"
            >
              {text}
            </text>
          </g>
        );
      })}
    </>
  );
}

export function HistogramChart({
  className,
  data,
  label = "API latency",
  format = (v) => `${Math.round(v)}ms`,
  percentiles = [50, 95, 99],
  tailCutoff = 99,
  bins: binTarget = 26,
  height = 320,
  status = "ready",
  onRetry,
}: HistogramChartProps) {
  const reduce = usePrefersReducedMotion();
  const [wrapRef, width] = useElementWidth<HTMLDivElement>();

  const { tail, cutoff, binsData, maxCount, pins } = useHistogramBins(
    data,
    tailCutoff,
    binTarget,
    percentiles,
  );
  const n = binsData.length;
  const total = data.length;
  const hasTail = tail.length > 0;
  const layout = histogramLayout(width, height, n, hasTail);
  const { xOf, yOf, countTicks, edgeTicks } = useHistogramScales(binsData, maxCount, layout);
  const { hover, setHover, svgRef, onMove, onKeyDown } = useHistogramHover(n, hasTail, layout);

  const active = activeBin(binsData, hover);
  const tailActive = hasTail && hover === n;
  const ready = width > 0;
  const { w, h } = layout;

  return (
    <div ref={wrapRef} className={cn("flex w-full flex-col text-muted-foreground/70", className)}>
      <Keyframes />

      <HistogramHeader
        label={label}
        status={status}
        total={total}
        n={n}
        hasTail={hasTail}
        tailCount={tail.length}
        cutoff={cutoff}
        pins={pins}
        format={format}
      />

      <ChartState
        status={status}
        height={height}
        variant="bars"
        empty={{
          title: "No samples yet",
          description: "Send the first measurements and the distribution will take shape.",
        }}
        onRetry={onRetry}
      >
        <div className="relative w-full" style={{ height }}>
          {!ready ? null : (
            <svg
              ref={svgRef}
              width={w}
              height={h}
              viewBox={`0 0 ${w} ${h}`}
              className="block w-full touch-pan-y select-none overflow-visible focus-visible:outline-hidden"
              role="img"
              aria-label={histogramAriaLabel(
                label,
                total,
                n,
                hasTail,
                tail.length,
                cutoff,
                pins,
                format,
              )}
              tabIndex={0}
              onKeyDown={onKeyDown}
              onBlur={() => setHover(null)}
              onPointerMove={(e) => onMove(e.clientX)}
              onPointerDown={(e) => onMove(e.clientX)}
              onPointerLeave={() => setHover(null)}
            >
              <HistogramAxes
                layout={layout}
                xOf={xOf}
                yOf={yOf}
                countTicks={countTicks}
                edgeTicks={edgeTicks}
                format={format}
              />

              <HistogramBars
                binsData={binsData}
                maxCount={maxCount}
                layout={layout}
                xOf={xOf}
                hover={hover}
                reduce={reduce}
              />

              <TailBin
                hasTail={hasTail}
                tailCount={tail.length}
                maxCount={maxCount}
                cutoff={cutoff}
                layout={layout}
                hover={hover}
                tailActive={tailActive}
                reduce={reduce}
                format={format}
              />

              <PercentilePins
                pins={pins}
                layout={layout}
                xOf={xOf}
                reduce={reduce}
                format={format}
              />
            </svg>
          )}
        </div>
      </ChartState>

      <p
        className="mt-2 h-4 font-mono text-[11px] tabular-nums text-muted-foreground transition-opacity duration-150"
        style={{ opacity: active ? 1 : 0 }}
        aria-live="polite"
      >
        {hoverText(tailActive, active, tail.length, cutoff, total, format)}
      </p>

      <ChartDataTable
        caption={`${label} — sample count by bin`}
        columns={["Range", "Count", "Share"]}
        rows={histogramRows(binsData, hasTail, tail.length, cutoff, total, format)}
      />
    </div>
  );
}
